pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 sendAmount, uint256 withdrawAmount, uint256 depositCount) public {
        vm.assume(caller != address(0) && address(c) != caller);
        vm.assume(sendAmount <= type(uint256).max - 1 ether);
        vm.assume(withdrawAmount <= 1 ether);

        // Fund the contract with some ether
        vm.deal(address(c), 1 ether);

        // Record initial state
        uint256 initOwnerBal = address(this).balance;
        uint256 initDepositsCount = c.depositsCount();
        uint256 initContractBal = address(c).balance;

        // Make some deposits via receive to change depositsCount
        for (uint256 i = 0; i < depositCount; i++) {
            vm.deal(address(this), 0.1 ether);
            (bool success, ) = address(c).call{value: 0.1 ether}("");
            vm.assume(success);
        }

        // Deposit via sendMoney
        vm.deal(address(this), sendAmount);
        c.sendMoney(caller, sendAmount);

        // Withdraw some amount if owner is caller
        if (caller == address(this)) {
            vm.deal(address(c), withdrawAmount + 1 ether);
            c.withdraw(withdrawAmount);
        }

        // Invariant: total ether in system is conserved plus deposits increment
        uint256 finalOwnerBal = address(this).balance;
        uint256 finalContractBal = address(c).balance;
        uint256 finalDepositsCount = c.depositsCount();

        // Rule: All ether sent to contract via sendMoney either stays in contract or goes to target
        // For any call sequence, the contract balance plus any sent amounts equal the initial balance plus deposits minus withdrawals
        // Simplified: depositsCount never decreases and contract balance changes predictably
        assertTrue(finalDepositsCount >= initDepositsCount);
    }
}

