import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, address target, uint256 value) public {
        // Only consider non-owner calls
        vm.assume(sender != address(this) && sender != address(0));
        vm.assume(target != address(0));
        // Ensure the owner is address(0) because the constructor sets owner = msg.sender
        // We need to avoid calling as owner, so set the owner to a known address
        // Actually the owner is the deployer (this contract). We want non-owner.
        vm.assume(sender != c.owner());
        // Give some ether to the sender for potential send
        vm.deal(sender, 1 ether);
        // Record depositsCount before
        uint256 before = c.depositsCount();
        // Prank and call sendMoney
        vm.prank(sender);
        // sendMoney may revert; we ignore revert and just check state if it doesn't
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, value));
        // If the call did not revert, then depositsCount should be >= before
        if (!ok) {
            // If it reverted, no state change - we can assert true trivially
            assertTrue(true);
        } else {
            uint256 after = c.depositsCount();
            // The only state variable depositsCount can change is via receive(), which increments.
            // sendMoney itself does not change depositsCount. So depositsCount must be >= before.
            assertTrue(after >= before);
        }
    }
}

